const body = $json.body || $json;
const { mode, event_type, map_id, user } = body;

const safeUser = (user || 'system').replace(/'/g, "''");
const safeEventType = (event_type || 'Shop->Prod').replace(/'/g, "''");

let sql;
if (mode === 'INSERT') {
  sql = `WITH _ctx AS (SELECT set_config('app.current_email', '${safeUser}', false))
INSERT INTO whatsfresh.lineage (account_id, event_type, source_batch_id, target_batch_id, created_at, created_by)
SELECT
  whatsfresh.c_getval('account_id')::integer,
  '${safeEventType}',
  whatsfresh.c_getval('source_batch_id')::integer,
  whatsfresh.c_getval('target_batch_id')::integer,
  now(),
  whatsfresh.c_getval('firstName')
FROM _ctx
RETURNING jsonb_build_object('success', true, 'mode', 'insert', 'data', to_jsonb(lineage.*)) as result`;
} else if (mode === 'DELETE') {
  if (!map_id) {
    return { json: { result: JSON.stringify({ success: false, error: 'DELETE requires map_id' }) } };
  }
  sql = `WITH _ctx AS (SELECT set_config('app.current_email', '${safeUser}', false))
DELETE FROM whatsfresh.lineage
WHERE id = ${parseInt(map_id)}
RETURNING jsonb_build_object('success', true, 'mode', 'hard-delete', 'data', to_jsonb(lineage.*)) as result`;
} else {
  return { json: { result: JSON.stringify({ success: false, error: 'Invalid mode: ' + mode }) } };
}

return { json: { sql } };
